function mergeWatchRanges(input){const rows=(Array.isArray(input)?input:[]).map(row=>[Math.max(0,Number(row?.[0])||0),Math.max(0,Number(row?.[1])||0)]).filter(row=>row[1]>row[0]).sort((a,b)=>a[0]-b[0]),merged=[];for(const row of rows){const last=merged[merged.length-1];if(last&&row[0]<=last[1]+.35)last[1]=Math.max(last[1],row[1]);else merged.push(row)}return merged.slice(-500)}
