 function startedVideos(){return HOME_VIDEOS_DATA.map(v=>({video:managedVideoDetails(v),progress:progressForVideo(v.id)})).filter(x=>x.progress.time>0).sort((a,b)=>Number(b.progress.updatedAt)-Number(a.progress.updatedAt))}
 function displayVideoTitle(video){if(!video)return'';return State.lang==='zh'?(video.titleZh||video.title||''):(video.title||video.titleZh||'')}
 function videoCardMarkup(raw,{showProgress=false}={}){const video=managedVideoDetails(raw),progress=progressForVideo(video.id),pct=Math.max(0,Math.min(100,Math.round(progress.percent||0))),title=escapeHtml(displayVideoTitle(video)||''),english=State.lang==='zh'&&video.titleZh&&video.title!==video.titleZh?`<p class="home-card-subtitle">${escapeHtml(video.title)}</p>`:'';return `<article class="home-video-card" data-video="${video.id}" data-category="${escapeHtml(video.category||'热门')}" tabindex="0"><div class="home-thumb"><img src="${video.cover}" alt="${title}"><span class="duration">${fmt(video.duration)}</span></div><div class="home-video-body"><h3>${title}</h3>${english}${showProgress&&pct>0?`<div class="learn-progress" aria-label="播放位置 ${pct}%"><i style="width:${pct}%"></i></div>`:''}<div class="home-card-foot"><span>${escapeHtml(video.creator||'Eastudy')}</span><span>${showProgress&&pct>0?`播放到 ${pct}%`:escapeHtml(video.level||'A2')}</span></div></div></article>`}
 function renderHomePriority(){if(renderEmptyHome())return;const started=startedVideos(),fallback=managedVideoDetails(HOME_VIDEOS_DATA[0]),entry=started[0]||{video:fallback,progress:progressForVideo(fallback.id)},video=entry.video,progress=entry.progress,pct=Math.max(0,Math.min(100,Math.round(progress.percent||0))),hasHistory=progress.time>0,routePath='/video/'+video.id;const card=$('#priorityResumeCard'),primary=$('#todayPrimaryAction');if(card)card.dataset.route=routePath;if(primary){primary.dataset.route=routePath;primary.textContent=hasHistory?'继续学习':'开始第一课'}const cover=$('#priorityResumeCover');if(cover){cover.src=video.cover||'assets/images/home_video_1.png';cover.alt=displayVideoTitle(video)}if($('#priorityResumeLabel'))$('#priorityResumeLabel').textContent=hasHistory?'继续上次学习':'开始你的第一个 Vlog';if($('#priorityResumeTitle'))$('#priorityResumeTitle').textContent=displayVideoTitle(video);if($('#priorityResumeProgress'))$('#priorityResumeProgress').textContent=hasHistory?`播放到 ${pct}%`:'尚未开始';if($('#priorityResumeTime'))$('#priorityResumeTime').textContent=hasHistory?`从 ${fmt(progress.time)} 继续`:`${fmt(video.duration)} · ${video.level||'A2'}`;if($('#priorityResumeBar'))$('#priorityResumeBar').style.width=pct+'%';document.querySelectorAll('.home-start').forEach(btn=>btn.dataset.route=routePath);const launcher=$('.progress-launcher');if(launcher)launcher.dataset.route=routePath}
 function renderHomeCategoryState(){ $$('#homeCategoryRow button').forEach(btn=>btn.classList.toggle('active',btn.dataset.cat===State.homeCategory)); }
 function syncHomeDiscoveryHeading(){const continuing=startedVideos().length>0&&State.homeCategory==='热门';if($('#continueTitle'))$('#continueTitle').textContent=State.lang==='en'?(continuing?'Continue Learning':'Recommended for You'):(continuing?'继续学习':'为你推荐');if($('#continueDesc'))$('#continueDesc').textContent=State.lang==='en'?(continuing?'Pick up from your real last position':'Chosen by level, topic, and length'):(continuing?'从本人实际观看位置接着学':'按难度、主题和时长选择')}
 function bindHomeCategoryButtons(){ $$('#homeCategoryRow button').forEach(btn=>btn.onclick=()=>{State.homeCategory=btn.dataset.cat;renderHomeCategoryState();renderHomeHomeSections();toast('已切换到「'+State.homeCategory+'」内容');logEvent('home.category',State.homeCategory);renderLogic()}) }
 function renderHomeHomeSections(){const all=HOME_VIDEOS_DATA.map(managedVideoDetails),recommended=itemsForCategory(all,State.homeCategory,4).sort((a,b)=>progressForVideo(a.id).time-progressForVideo(b.id).time),started=startedVideos().slice(0,4),videoRows=started.length&&State.homeCategory==='热门'?started.map(x=>x.video):recommended;syncHomeDiscoveryHeading();$('#videoCards').innerHTML=videoRows.length?videoRows.map(v=>videoCardMarkup(v,{showProgress:true})).join(''):`<div class="home-inline-empty"><b>暂时没有符合条件的视频</b><span>清除筛选后看看其他真实 Vlog。</span><button type="button" id="clearHomeFilter">查看热门内容</button></div>`;$('#clearHomeFilter')?.addEventListener('click',()=>{State.homeCategory='热门';renderHomeCategoryState();renderHomeHomeSections()});const collections=itemsForCategory(HOME_COLLECTIONS_DATA,State.homeCategory,5).filter(c=>c.count>0);$('#collectionCards').innerHTML=collections.length?collections.map(c=>`<article class="home-collection-card" data-route="/compilation/${c.id}" data-category="${c.category}" tabindex="0"><div class="collection-img"><img src="${c.cover}" alt="${c.title}"></div><div class="collection-info"><b>${c.title}</b><span>${c.count} 个视频</span></div></article>`).join(''):`<div class="home-inline-empty"><b>这个主题的合集正在准备</b><span>你可以先从推荐视频开始。</span></div>`;const latest=all.filter(v=>v.publishedAt).sort((a,b)=>Date.parse(b.publishedAt)-Date.parse(a.publishedAt));$('#homeLatestCards').innerHTML=latest.slice(0,4).map(v=>videoCardMarkup(v)).join('');const daily=HOME_DAILY_MAP[State.homeCategory]||HOME_DAILY_MAP['热门'],dailyVideo=recommended[0]||all[0];const dailyBox=$('.daily-pick');if(dailyBox)dailyBox.hidden=!dailyVideo;const dailyImg=document.querySelector('.daily-thumb img');if(dailyImg){dailyImg.src=dailyVideo?.cover||daily.image;dailyImg.alt=displayVideoTitle(dailyVideo)||daily.title}const dailyH=$('.daily-pick h4'),dailyP=$('.daily-pick p');if(dailyH)dailyH.textContent=displayVideoTitle(dailyVideo)||daily.title;if(dailyP)dailyP.textContent=`${fmt(dailyVideo?.duration||0)} · ${dailyVideo?.level||'A2'}`;document.querySelectorAll('.daily-pick [data-route]').forEach(btn=>btn.dataset.route='/video/'+(dailyVideo?.id||2805));renderHomeGoal();renderHomePriority();bindCards();}

