function localDayKey(date=new Date()){const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return `${y}-${m}-${d}`}
function addStudySeconds(seconds){const amount=Math.max(0,Number(seconds)||0);if(!amount)return;const rows=Storage.get('studySessions',{}),key=localDayKey();rows[key]=Math.max(0,Number(rows[key])||0)+amount;Storage.set('studySessions',rows)}
function studySummary(){const sessions=Storage.get('studySessions',{}),keys=Object.keys(sessions).filter(key=>Number(sessions[key])>0).sort(),today=localDayKey(),todaySeconds=Number(sessions[today])||0,totalSeconds=Object.values(sessions).reduce((sum,value)=>sum+(Number(value)||0),0);let streak=0,cursor=new Date();while(Number(sessions[localDayKey(cursor)])>0){streak+=1;cursor.setDate(cursor.getDate()-1)}const days=Array.from({length:7},(_,index)=>{const date=new Date();date.setDate(date.getDate()-(6-index));const key=localDayKey(date),mins=Math.floor((Number(sessions[key])||0)/60);return {key,wk:['日','一','二','三','四','五','六'][date.getDay()],date:date.getDate(),mins,done:mins>0,today:key===today}});return {sessions,keys,todaySeconds,totalSeconds,streak,days}}
