function syncPasswordStatus(){const target=$('#accountPasswordStatus');if(target)target.textContent=passwordStatusText(StudentAuth.context?.profile)}
function syncSessionUI(){const active=Boolean(StudentAuth.context?.user&&isStudentProfile(StudentAuth.context?.profile));document.body.classList.toggle('session-signed-out',!active);document.getElementById('signinBackdrop')?.classList.toggle('show',!active);return active}
function togglePasswordForm(force){const form=$('#accountPasswordForm'),button=$('#accountPasswordToggle');if(!form)return;const open=typeof force==='boolean'?force:form.hidden;form.hidden=!open;if(button)button.textContent=open?'收起':'设置密码';if(open)requestAnimationFrame(()=>$('#accountNewPassword')?.focus())}
function openAccountDialog(){closeAccountMenus();syncPasswordStatus();document.getElementById('accountBackdrop')?.classList.add('show')}
function openPreferences(){closeAccountMenus();document.getElementById('accountBackdrop')?.classList.remove('show');document.getElementById('settingsBackdrop')?.classList.add('show')}
async function performLogout(){stopAllMedia('logout',{saveProgress:true,closeOverlays:true});await window.EastudyAuth?.signOut('student');await window.EastudyCloudContent?.clearMediaSession();StudentAuth.context=null;StudentAuth.pendingContext=null;State.membership=null;State.learningQueue=null;window.__eastudyStudentId='signed-out';closeAccountMenus();document.getElementById('accountBackdrop')?.classList.remove('show');closeVipRedeemDialog();if($('#goalOnboarding'))$('#goalOnboarding').hidden=true;document.body.classList.remove('goal-onboarding-open');syncMembershipUI(null);syncSessionUI();toast(State.lang==='en'?'Signed out':'已退出登录')}
function syncMembershipUI(membership){const expiresAt=membership?.expiresAt||membership?.expires_at||null,expires=expiresAt?new Date(expiresAt):null,active=Boolean(membership?.active&&expires&&expires.getTime()>Date.now());State.membership=membership?{...membership,active,expiresAt:expires?.toISOString()||null}:null;const date=active?expires.toLocaleDateString('zh-CN'):'';const days=active?Math.max(1,Math.ceil((expires.getTime()-Date.now())/86400000)):0;document.querySelectorAll('.vip-badge').forEach(x=>{x.textContent='VIP';x.classList.toggle('is-active',active)});document.querySelectorAll('.vip-status-card').forEach(x=>x.classList.toggle('is-active',active));document.querySelectorAll('.vip-expiry').forEach(x=>x.textContent=active?'有效期至 '+date:'普通学员 · 未激活 VIP');document.querySelectorAll('.vip-days').forEach(x=>x.textContent=active?'剩余 '+days+' 天':'输入激活码后开通');const status=$('#accountMembershipStatus');if(status)status.textContent=active?'Eastudy Pro · 有效期至 '+date:'普通学员';}
async function refreshMembership(){if(!StudentAuth.context?.user){syncMembershipUI(null);return null}const result=await window.EastudyData?.getMembership?.();if(!result){syncMembershipUI(null);return null}if(result.error){syncMembershipUI(null);console.warn('Membership lookup failed',result.error);return null}syncMembershipUI(result.membership);return result.membership}
function openVipRedeemDialog(){closeAccountMenus();const box=$('#vipRedeemBackdrop'),input=$('#vipRedeemCode'),message=$('#vipRedeemMessage');if(!StudentAuth.context?.user){toast('请先登录学生账号');return}if(message){message.textContent='';message.dataset.kind=''}if(input)input.value='';box?.classList.add('show');requestAnimationFrame(()=>input?.focus())}
function closeVipRedeemDialog(){const box=$('#vipRedeemBackdrop');box?.classList.remove('show')}
async function submitVipRedeem(){const input=$('#vipRedeemCode'),button=$('#vipRedeemSubmit'),message=$('#vipRedeemMessage'),code=String(input?.value||'').trim();const show=(text,kind='error')=>{if(message){message.textContent=text;message.dataset.kind=kind}};if(!code){show('请输入激活码');input?.focus();return}button.disabled=true;button.textContent='正在验证…';show('');const result=await window.EastudyData?.redeemMembership?.(code);button.disabled=false;button.textContent='立即激活';if(!result||result.error){const raw=String(result?.error?.message||'').toLowerCase();show(raw.includes('invalid')||raw.includes('used')||raw.includes('expired')?'激活码无效、已使用或已过期':'激活失败，请稍后重试');return}syncMembershipUI(result.membership);show('激活成功，会员权益已经生效','success');setTimeout(closeVipRedeemDialog,900)}
