function studentAuthErrorMessage(error,register){const raw=String(error?.message||'').toLowerCase();if(!register){if(raw.includes('phone not confirmed')||raw.includes('phone_not_confirmed'))return'该手机号已创建账号，但尚未完成手机号确认；请联系管理员处理';if(raw.includes('invalid login credentials')||raw.includes('invalid_credentials'))return'账号或密码错误';if(raw.includes('rate limit')||raw.includes('too many'))return'登录尝试过于频繁，请稍后再试';return'登录失败，请检查账号状态后重试'}if(raw.includes('already registered')||raw.includes('already been registered')||raw.includes('user already exists'))return'该手机号已经注册，请直接登录';if(raw.includes('password')&&(raw.includes('least')||raw.includes('short')||raw.includes('weak')))return'密码强度不足，请至少输入 6 位密码';if(raw.includes('rate limit')||raw.includes('too many'))return'操作过于频繁，请稍后再试';return'注册失败，请检查手机号和密码后重试'}
function otpErrorMessage(error,phase){const raw=String(error?.message||'').toLowerCase();if(raw.includes('rate')||raw.includes('too many')||raw.includes('429'))return'操作过于频繁，请稍后再试';if(raw.includes('provider')||raw.includes('sms')&&raw.includes('disabled'))return'验证码服务尚未配置，请稍后使用';if(raw.includes('not found')||raw.includes('signup')&&raw.includes('disabled'))return'该账号还没有注册，请先注册';if(phase==='verify'||raw.includes('token')||raw.includes('otp')||raw.includes('expired'))return'验证码错误或已失效，请重新获取';return'验证码发送失败，请稍后重试'}
