function bindHomeHeroCarousel(){
  const hero=document.querySelector('.home-hero'),dots=[...document.querySelectorAll('.hero-dots i')]; if(!hero||!dots.length||hero.dataset.carouselBound)return;
  hero.dataset.carouselBound='1'; let index=0; const slides=[{title:'Better English.<br>A Brighter You.',desc:'在真实的世界里，遇见更好的自己',image:"url('assets/images/flower_frame.png')"},{title:'Learn in Real Context.',desc:'每天十分钟，把听懂变成习惯',image:"url('assets/images/home_daily_pick.png')"},{title:'Small Steps, Real Progress.',desc:'从一句话开始，完成今天的学习',image:"url('assets/images/home_collection_1.png')"}];
  const paint=i=>{index=(i+slides.length)%slides.length;const x=slides[index];hero.style.backgroundImage=x.image;const h=hero.querySelector('h1'),p=hero.querySelector('p');if(h)h.innerHTML=x.title;if(p)p.textContent=x.desc;dots.forEach((d,j)=>{d.classList.toggle('active',j===index);d.setAttribute('aria-pressed',String(j===index))});};
  dots.forEach((d,i)=>{d.setAttribute('role','button');d.setAttribute('tabindex','0');d.setAttribute('aria-label',`切换到首页精选内容 ${i+1}`);d.setAttribute('aria-pressed',String(i===index));d.onclick=()=>paint(i);d.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();paint(i)}}});
  let startX=0,startY=0;hero.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;startX=e.clientX;startY=e.clientY;hero.dataset.pause='1';try{hero.setPointerCapture?.(e.pointerId)}catch{}});hero.addEventListener('pointerup',e=>{if(!startX)return;const dx=e.clientX-startX,dy=e.clientY-startY;startX=startY=0;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.2)paint(index+(dx<0?1:-1));delete hero.dataset.pause});hero.addEventListener('pointercancel',()=>{startX=startY=0;delete hero.dataset.pause});hero.addEventListener('mouseenter',()=>hero.dataset.pause='1');hero.addEventListener('mouseleave',()=>delete hero.dataset.pause);setInterval(()=>{if(!hero.dataset.pause)paint(index+1)},7000);
}async function bootHome(){await MockAPI.home();applyLanguage();renderHomeCreators();renderHomeCategoryState();renderHomeHomeSections();bindHomeCategoryButtons();renderStreakCalendar();renderHotTags();bindHomeHeroCarousel();bindHomeAccount();refreshStats();hydrateIcons(document.getElementById('homePage'));}

