function findSentence(t){const a=DATA.sentences;if(!a.length)return -1;let lo=0,hi=a.length-1;while(lo<=hi){const m=(lo+hi)>>1,d=a[m];if(t<d.s)hi=m-1;else if(t>=d.e)lo=m+1;else return m}return Math.max(0,Math.min(a.length-1,lo-1))}
