const VOCAB_DAY=86400000;
const VocabReview={queue:[],index:0,revealed:false};
function vocabKey(word){return normalizePhrase(word)}
function vocabMetaMap(){return Storage.get('vocabMeta',{})||{}}
function ensureVocabMeta(word,seed={}){const key=vocabKey(typeof word==='string'?word:word.word),map=vocabMetaMap();if(!map[key]){const source=typeof word==='string'?{word}:word;map[key]={state:seed.state||source.state||'new',addedAt:seed.addedAt||Date.now(),lastReviewedAt:null,nextReviewAt:seed.nextReviewAt??(source.state==='review'?Date.now()-60000:source.state==='mastered'?Date.now()+14*VOCAB_DAY:null),correctStreak:source.state==='mastered'?2:0,sourceVideoId:seed.sourceVideoId||activeVideoId?.()||2805};Storage.set('vocabMeta',map)}return map[key]}
function updateVocabMeta(word,patch){const key=vocabKey(word),map=vocabMetaMap(),current=map[key]||ensureVocabMeta(word);map[key]={...current,...patch};Storage.set('vocabMeta',map);const info=wordInfo(word);void window.EastudyData?.setVocabulary({active:true,wordKey:key,word,phonetic:info.phon||'',meaning:info.meaning||'',context:DATA.sentences[State.currentSentence]?.en||'',state:map[key].state||'new',correctStreak:map[key].correctStreak||0,addedAt:map[key].addedAt?new Date(map[key].addedAt).toISOString():undefined,lastReviewedAt:map[key].lastReviewedAt?new Date(map[key].lastReviewedAt).toISOString():null,nextReviewAt:map[key].nextReviewAt?new Date(map[key].nextReviewAt).toISOString():null});return map[key]}
function isVocabSaved(word){const key=vocabKey(word);return Storage.get('vocab',[]).some(x=>vocabKey(x)===key)}
function removeVocabWord(word){const key=vocabKey(word),arr=Storage.get('vocab',[]).filter(w=>vocabKey(w)!==key);Storage.set('vocab',arr);const map=vocabMetaMap();delete map[key];Storage.set('vocabMeta',map);void window.EastudyData?.setVocabulary({active:false,wordKey:key,word})}
function vocabStateLabel(v){if(v.state==='mastered')return '已掌握';if(v.state==='review')return v.nextReviewAt&&v.nextReviewAt>Date.now()?'已安排':'待复习';return '新词'}
function currentVocabFilter(){return $('.vocab-filter-tabs .active')?.dataset.vocabFilter||'all'}
function updateVocabStats(entries=combinedVocab()){const now=Date.now(),weekAgo=now-7*VOCAB_DAY,due=entries.filter(v=>v.state==='review'&&(!v.nextReviewAt||v.nextReviewAt<=now)).length,mastered=entries.filter(v=>v.state==='mastered').length;$('#vocabTotalCount')&&($('#vocabTotalCount').textContent=entries.length);$('#vocabWeeklyCount')&&($('#vocabWeeklyCount').textContent=entries.filter(v=>v.addedAt>=weekAgo).length);$('#vocabDueCount')&&($('#vocabDueCount').textContent=due);$('#vocabMasteryRate')&&($('#vocabMasteryRate').textContent=(entries.length?Math.round(mastered/entries.length*100):0)+'%')}
function exportVocabulary(){const esc=v=>'"'+String(v??'').replace(/"/g,'""')+'"',rows=combinedVocab(),csv='\uFEFFword,phonetic,meaning,state,context,next_review\n'+rows.map(v=>[v.word,v.phon,v.meaning,v.state,v.context,v.nextReviewAt?new Date(v.nextReviewAt).toISOString():''].map(esc).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='eastudy-vocabulary.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast(`已导出 ${rows.length} 个词汇`)}
function reviewQueue(preferred=''){const all=combinedVocab(),now=Date.now(),due=all.filter(v=>v.state==='new'||(v.state==='review'&&(!v.nextReviewAt||v.nextReviewAt<=now)));const fallback=all.filter(v=>v.state!=='mastered');let queue=due.length?due:fallback.length?fallback:all;if(preferred){const key=vocabKey(preferred);queue=[...queue.filter(v=>vocabKey(v.word)===key),...queue.filter(v=>vocabKey(v.word)!==key)]}return queue}
function openVocabReview(preferred=''){VocabReview.queue=reviewQueue(preferred);VocabReview.index=0;VocabReview.revealed=false;if(!VocabReview.queue.length){toast('生词本还是空的');return}$('#vocabReviewPanel').hidden=false;renderVocabReview();$('#vocabReviewPanel').scrollIntoView({behavior:'smooth',block:'start'})}
function closeVocabReview(){$('#vocabReviewPanel').hidden=true;VocabReview.queue=[];VocabReview.index=0;VocabReview.revealed=false}
function renderVocabReview(){const v=VocabReview.queue[VocabReview.index];if(!v){closeVocabReview();renderVocabPage(currentVocabFilter(),$('#vocabSearch')?.value||'');toast('本轮复习完成');return}VocabReview.revealed=false;$('#vocabReviewProgress').textContent=`${VocabReview.index+1} / ${VocabReview.queue.length}`;$('#vocabReviewBar').style.width=`${(VocabReview.index+1)/VocabReview.queue.length*100}%`;$('#vocabReviewWord').textContent=v.word;$('#vocabReviewPhon').textContent=v.phon||'';$('#vocabReviewContext').textContent=`“${v.context}”`;$('#vocabReviewMeaning').textContent=v.meaning;$('#vocabReviewAnswer').hidden=true;$('#vocabReviewActions').hidden=true;$('#vocabReviewReveal').hidden=false;$('#vocabReviewLabel').textContent='先回忆，再显示答案';hydrateIcons($('#vocabReviewPanel'))}
function revealVocabReview(){VocabReview.revealed=true;$('#vocabReviewAnswer').hidden=false;$('#vocabReviewActions').hidden=false;$('#vocabReviewReveal').hidden=true;$('#vocabReviewLabel').textContent='根据真实记忆情况选择'}
function gradeVocabReview(known){const v=VocabReview.queue[VocabReview.index];if(!v)return;const old=ensureVocabMeta(v),streak=known?(old.correctStreak||0)+1:0,state=known&&streak>=2?'mastered':'review',delay=known?(state==='mastered'?14*VOCAB_DAY:VOCAB_DAY):10*60*1000;updateVocabMeta(v.word,{state,correctStreak:streak,lastReviewedAt:Date.now(),nextReviewAt:Date.now()+delay});VocabReview.index+=1;renderVocabReview()}
function speechWord(word){const text=String(word||'').trim(),status=$('#pronunciationStatus');if(!text||!('speechSynthesis'in window)){if(status)status.textContent='当前浏览器暂不支持语音合成';return}const dialect=State.settings.pronunciationDialect==='en-US'?'en-US':'en-GB',label=dialect==='en-US'?'美音':'英音',generation=State.mediaGeneration;window.speechSynthesis.cancel();const voices=window.speechSynthesis.getVoices?.()||[],exact=voices.find(v=>String(v.lang).toLowerCase()===dialect.toLowerCase()),english=voices.find(v=>String(v.lang).toLowerCase().startsWith('en')),u=new SpeechSynthesisUtterance(text);u.lang=dialect;if(exact||english)u.voice=exact||english;u.onstart=()=>{if(generation!==State.mediaGeneration){window.speechSynthesis.cancel();return}if(status)status.textContent=`正在播放${label}：${text}`};u.onend=()=>{if(status&&generation===State.mediaGeneration)status.textContent=`点击扬声器播放${label}`};u.onerror=()=>{if(status&&generation===State.mediaGeneration)status.textContent='发音播放失败，请重试'};window.speechSynthesis.speak(u)}
function renderCollectionPro(filter='all',query=''){const id=activeCollectionId();let rows=DATA.videos.filter(v=>id===36||(v.collectionIds||[]).map(String).includes(String(id))).map(v=>{const progress=progressForVideo(v.id),captions=(window.ZoContent?.listSentences?.(v.id)||[]).length>0;return {...v,progress:Math.round(progress.percent||0),coverage:Math.round(progress.watchCoveragePercent||0),completed:Boolean(progress.completed),img:v.cover||'assets/images/home_video_1.png',captions}});if(filter==='learning')rows=rows.filter(x=>x.progress>0&&!x.completed);if(filter==='done')rows=rows.filter(x=>x.completed);if(filter==='new')rows=rows.filter(x=>x.progress===0);if(query)rows=rows.filter(x=>(x.title+x.creator).toLowerCase().includes(query.toLowerCase()));$('#collectionVideoCards').innerHTML=rows.length?rows.map(v=>`<article class="collection-video-row" data-video="${v.id}" tabindex="0"><div class="collection-video-thumb"><img src="${v.img}" alt="${escapeHtml(displayVideoTitle(v))}"><span>${fmt(v.duration)}</span></div><div class="collection-video-info"><h3>${escapeHtml(displayVideoTitle(v))}</h3><p>${escapeHtml(v.creator||'Eastudy')} · ${escapeHtml(v.level||'A2')}</p><div class="collection-video-tags">${v.captions?'<span>双语字幕</span><span>逐句精听</span>':'<span>字幕准备中</span>'}<span>${v.completed?'已完成':v.progress?'学习中':'未学习'}</span></div></div><div class="row-progress"><span>${v.progress?`播放位置 ${v.progress}% · 有效覆盖 ${v.coverage}%`:'尚未开始'}</span><div class="row-progress-line"><i style="width:${v.progress}%"></i></div></div><div class="row-action"><button>${v.progress?'继续学习':'开始学习'}</button></div></article>`).join(''):`<div class="empty-state"><i data-icon="search"></i><h3>没有找到匹配内容</h3><p>换一个关键词或筛选状态试试。</p></div>`;hydrateIcons($('#collectionVideoCards'));bindCards()}
