function currentLearningPlan(){const saved=Storage.get('learningPlan',{})||{},daily=[10,20,40,60].includes(Number(saved.dailyMinutes))?Number(saved.dailyMinutes):20;return {track:LEARNING_TRACKS.some(x=>x.id===saved.track)?saved.track:'general',dailyMinutes:daily,selfLevel:saved.selfLevel||'unsure',timezone:saved.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Shanghai',onboardingVersion:Number(saved.onboardingVersion)||0,revision:Number(saved.revision)||0}}
function learningTrack(id=currentLearningPlan().track){return LEARNING_TRACKS.find(x=>x.id===id)||LEARNING_TRACKS[0]}
function queueSourceVideos(){const managed=window.ZoContent?.listVideos?.({publishedOnly:true})||[];return (managed.length?managed:HOME_VIDEOS_DATA.map(managedVideoDetails)).map(video=>({...video,mediaUrl:video.mediaUrl||managedVideoDetails(video).mediaUrl||''}))}
function createLearningQueue({preferredVideoId=null,source='goal',collectionId=null}={}){const plan=currentLearningPlan(),engine=window.EastudyLearningQueue;if(!engine)return null;return engine.create({videos:queueSourceVideos(),goalId:plan.track,preferredVideoId,source,collectionId,loop:true})}
function renderHomeGoal(){const plan=currentLearningPlan(),track=learningTrack(plan.track),pool=window.EastudyLearningQueue?.eligibleVideos(queueSourceVideos(),plan.track)||[],button=$('#homeGoalStart');if($('#homeGoalName'))$('#homeGoalName').textContent=track.name;if($('#homeGoalMeta'))$('#homeGoalMeta').textContent=pool.length?`每天 ${plan.dailyMinutes} 分钟 · ${pool.length} 条目标视频自动连播`:`每天 ${plan.dailyMinutes} 分钟 · 审核课程内容建设中`;if(button){button.disabled=!pool.length;button.querySelector('span').textContent=pool.length?'开始目标学习':'内容建设中'}}
function renderGoalOnboarding(){const plan=currentLearningPlan(),root=$('#goalOnboardingOptions');if(!root)return;root.innerHTML=LEARNING_TRACKS.map(track=>`<button type="button" data-onboarding-goal="${track.id}" data-status="${track.status}" class="${track.id===plan.track?'active':''}"><b>${track.name}</b><span>${track.focus}</span>${track.status==='planned'?'<em>课程内容建设中，可先设为目标</em>':''}</button>`).join('');$('#goalOnboardingMinutes').value=String(plan.dailyMinutes);$('#goalOnboardingLevel').value=plan.selfLevel;$$('[data-onboarding-goal]').forEach(button=>button.onclick=()=>{$$('[data-onboarding-goal]').forEach(x=>x.classList.toggle('active',x===button))})}
function showGoalOnboarding(force=false){if(!StudentAuth.context?.user)return;const plan=currentLearningPlan();if(!force&&plan.onboardingVersion>=1)return;renderGoalOnboarding();const dialog=$('#goalOnboarding');if(dialog)dialog.hidden=false;document.body.classList.add('goal-onboarding-open')}
function maybeShowGoalOnboarding(){showGoalOnboarding(false)}
async function persistLearningPlan(input,{closeOnboarding=false}={}){const plan={...currentLearningPlan(),...input,onboardingVersion:1};Storage.set('learningPlan',plan);renderLearningPlan();renderHomeGoal();const result=await window.EastudyData?.saveLearningGoalProfile?.(plan);if(closeOnboarding){$('#goalOnboarding').hidden=true;document.body.classList.remove('goal-onboarding-open')}if(result?.error)toast('目标已保存在本设备，云端同步将在数据库更新后生效');else toast('学习目标已保存并同步');return result}
function startGoalLearning(){const queue=createLearningQueue();if(!queue?.ids?.length){toast('该目标的审核内容正在建设中，请先调整学习目标');showGoalOnboarding(true);return}State.learningQueue=queue;route('/video/'+queue.ids[0]);void window.EastudyData?.logStudyEvent('goal_queue_started',{payload:{goalId:queue.goalId,count:queue.ids.length}})}
function startCollectionLearning(collectionId,preferredVideoId=null){const queue=createLearningQueue({preferredVideoId,source:'collection',collectionId});if(!queue?.ids?.length){toast('这个合集暂时没有可播放的视频');return}State.learningQueue=queue;route('/video/'+(preferredVideoId||queue.ids[0]));void window.EastudyData?.logStudyEvent('collection_queue_started',{payload:{collectionId:String(collectionId),count:queue.ids.length}})}
function renderLearningPlan(){const select=$('#learningTrackSelect'),minutes=$('#dailyMinutesSelect'),saved=currentLearningPlan(),track=learningTrack(saved.track),daily=saved.dailyMinutes;if(select){select.innerHTML=LEARNING_TRACKS.map(x=>`<option value="${x.id}">${x.name}${x.status==='planned'?'（内容建设中）':''}</option>`).join('');select.value=track.id}if(minutes)minutes.value=String(daily);const pool=window.EastudyLearningQueue?.eligibleVideos(queueSourceVideos(),track.id)||[],ready=pool.length>0;if($('#learningPlanSummary'))$('#learningPlanSummary').textContent=ready?`当前路线：${track.name} · 每天 ${daily} 分钟 · ${track.focus}`:`${track.name} 已纳入课程体系，当前没有审核通过的视频；可暂时选择“综合英语提升”。`;const related=LEARNING_TRACKS.filter(x=>x.group===track.group||x.id===track.id).slice(0,5);if($('#learningTrackGrid'))$('#learningTrackGrid').innerHTML=related.map(x=>{const count=window.EastudyLearningQueue?.eligibleVideos(queueSourceVideos(),x.id)?.length||0;return `<button type="button" data-learning-track="${x.id}" class="${x.id===track.id?'active':''}"><b>${x.name}</b><span>${x.focus}</span><em>${count?`${count} 条可学视频`:'内容建设中'}</em></button>`}).join('');const tasks=ready?[['情境输入',Math.max(4,Math.round(daily*.4)),'观看 Vlog 并理解主旨'],['词语积累',Math.max(3,Math.round(daily*.25)),'学习目标词汇与短语'],['发音跟读',Math.max(3,Math.round(daily*.2)),'英音/美音辨听与原句跟读'],['间隔复习',Math.max(2,Math.round(daily*.15)),'复习到期生词与收藏句']]:[['路线准备中',daily,'等待该目标的审核内容上线']];if($('#todayPlanList'))$('#todayPlanList').innerHTML=tasks.map(([name,time,copy],i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><b>${name}</b><small>${copy}</small></div><em>${time} 分钟</em></article>`).join('');$$('[data-learning-track]').forEach(x=>x.onclick=()=>void persistLearningPlan({track:x.dataset.learningTrack,dailyMinutes:daily}))}
function saveLearningPlanFromControls(){const track=$('#learningTrackSelect')?.value||'general',dailyMinutes=Number($('#dailyMinutesSelect')?.value)||20;void persistLearningPlan({track,dailyMinutes})}
function bootLearning(){renderLearningPlan();const vals=studySummary().days.map(day=>day.mins);$('#learningChart').innerHTML=vals.map(v=>`<div class="chart-bar"><b>${v}m</b><i style="height:${v?Math.max(12,Math.min(150,v/40*150)):2}px"></i></div>`).join('');const qs=reviewQueue().slice(0,4);$('#reviewQueue').innerHTML=qs.length?qs.map(x=>`<div class="review-word"><b>${x.word}</b><span>${x.meaning}</span><button data-review-queue="${x.word}">复习</button></div>`).join(''):'<div class="empty-state compact"><p>暂无待复习词汇。</p></div>';const recent=startedVideos().slice(0,3);$('#recentLearning').innerHTML=recent.length?recent.map(x=>`<div class="recent-row" data-video="${x.video.id}"><img src="${x.video.cover}"><div><b>${escapeHtml(displayVideoTitle(x.video))}</b><span>${Math.round(x.progress.percent||0)}% · ${escapeHtml(x.video.creator||'Eastudy')}</span></div><i data-icon="chevron-right"></i></div>`).join(''):'<div class="empty-state compact"><p>开始播放后，这里会显示真实学习记录。</p></div>';$('#learningWordCount').textContent=combinedVocab().filter(v=>v.state==='mastered').length;$$('#reviewQueue [data-review-queue]').forEach(x=>x.onclick=()=>{route('/vocabulary');setTimeout(()=>openVocabReview(x.dataset.reviewQueue),80)});$$('#recentLearning [data-video]').forEach(x=>x.onclick=()=>route('/video/'+x.dataset.video));hydrateIcons($('#learningPage'))}
function openSearch(initial=''){const b=$('#searchBackdrop');b.classList.add('show');const input=$('#globalSearchInput');input.value=initial;renderGlobalSearch(initial);setTimeout(()=>input.focus(),30)}
function closeSearch(){$('#searchBackdrop').classList.remove('show')}
function renderGlobalSearch(q=''){const rows=[...HOME_VIDEOS_DATA.map(x=>({type:'视频',title:displayVideoTitle(managedVideoDetails(x)),sub:x.creator,img:x.cover,route:'/video/'+x.id})),...HOME_COLLECTIONS_DATA.filter(x=>x.count>0).map(x=>({type:'合集',title:x.title,sub:x.count+' 个视频',img:x.cover,route:'/compilation/'+x.id})),...UI_CREATORS.map(x=>({type:'博主',title:x.name,sub:x.bio,img:x.avatar,route:x.route}))];const filtered=q.trim()?rows.filter(x=>(x.title+x.sub+x.type).toLowerCase().includes(q.toLowerCase())):rows.slice(0,6);$('#globalSearchResults').innerHTML=filtered.length?filtered.slice(0,12).map(x=>`<article class="search-result-row" data-search-route="${x.route}"><img src="${x.img}" alt="${x.title}"><div><b>${x.title}</b><p>${x.sub}</p></div><span>${x.type}</span></article>`).join(''):`<div class="empty-state"><i data-icon="search"></i><h3>没有找到结果</h3><p>试试“旅行”“Jojo”或“职场”。</p></div>`;$$('[data-search-route]').forEach(x=>x.onclick=()=>{closeSearch();route(x.dataset.searchRoute)});hydrateIcons($('#globalSearchResults'))}
