function hydrateManagedContent(){
  if(!window.ZoContent)return;
  try{
    const published=window.ZoContent.listVideos({publishedOnly:true});
    {
      const normalized=published.map(v=>({id:Number(v.id),title:v.title,titleZh:v.titleZh||'',creatorId:v.creatorId||'',creator:v.creator||'Eastudy',duration:Number(v.duration)||30,level:v.level||'A2',cover:v.cover||'assets/images/home_video_1.png',mediaUrl:v.mediaUrl||'',date:(v.publishedAt||v.updatedAt||'').slice(0,10),publishedAt:v.publishedAt||null,category:v.category||'热门',collectionIds:v.collectionIds||[],goalIds:v.goalIds||[],goalMappings:v.goalMappings||[]}));
      DATA.videos.splice(0,DATA.videos.length,...normalized);
      const studentVideos=published.map(v=>({id:Number(v.id),title:v.title,titleZh:v.titleZh||'',creatorId:v.creatorId||'',creator:v.creator||'Eastudy',level:v.level||'A2',duration:Number(v.duration)||30,cover:v.cover||'assets/images/home_video_1.png',mediaUrl:v.mediaUrl||'',category:v.category||'热门',publishedAt:v.publishedAt||null,collectionIds:v.collectionIds||[],goalIds:v.goalIds||[],goalMappings:v.goalMappings||[]}));
      HOME_VIDEOS_DATA.splice(0,HOME_VIDEOS_DATA.length,...studentVideos);
    }
    const cols=window.ZoContent.listCollections?.()||[];
    {const studentCollections=cols.filter(x=>x.status==='PUBLISHED').map(c=>({id:Number(c.id),title:c.title,count:published.filter(v=>(v.collectionIds||[]).map(String).includes(String(c.id))).length,cover:c.cover||'assets/images/home_collection_1.png',category:c.title.includes('旅行')||c.title.includes('Travel')?'旅行':c.title.includes('美食')?'美食':c.title.includes('心理')?'心理':c.title.includes('自然')?'自然':c.title.includes('科技')?'科技':c.title.includes('学习')?'职场':c.title.includes('演讲')?'教育':'热门'}));HOME_COLLECTIONS_DATA.splice(0,HOME_COLLECTIONS_DATA.length,...studentCollections)}
    const creators=window.ZoContent.listCreators?.()||[];
    if(creators.length){const managedCreators=creators.filter(c=>c&&c.name&&!/^(null|undefined)$/i.test(String(c.name).trim())).map(c=>{const videos=published.filter(v=>String(v.creatorId||'')===String(c.id)),category=videos.map(v=>v.category).find(Boolean)||c.category||'日常生活';return {id:String(c.id),name:String(c.name).trim(),initial:String(c.name).trim().slice(0,1).toUpperCase(),bio:c.bio||'真实语境英语内容',category,videos:videos.length,learners:c.learners||'—',avatar:c.avatar||'',route:'/creator/'+encodeURIComponent(String(c.id)),channelUrl:c.channelUrl||''}});UI_CREATORS.splice(0,UI_CREATORS.length,...managedCreators)}
  }catch(e){console.warn('Eastudy managed content hydration skipped',e)}
}
